Given a square matrix, find the adjoint and inverse of the matrix. We strongly recommend you to refer determinant of matrix as a prerequisite for this. Adjoint (or Adjugate) of a matrix is the matrix obtained by taking the transpose of the cofactor matrix of a given square matrix is called its Adjoint or Adjugate matrix. The Adjoint of any square matrix 'A' (say) is represented as Adj(A). Example: Input:  A[][]= [[5, -2, 2, 7], [1, 0, 0, 3], [-3, 1, 5, 0], [3, -1, -9, 4]]Output: Adj(A) = [[-12, 76, -60, -36], [-56, 208, -82, -58], [4, 4, -2, -10], [4, 4, 20, 12]],Inverse(A) = [[-0.136, 0.864, -0.682, -0.409], [-0.636, 2.364, -0.932, -0.659], [0.045, 0.045, -0.023, -0.114], [0.045, 0.045, 0.227, 0.136]]Important properties: Product of a square matrix A[][] with its adjoint yields a diagonal matrix, where each diagonal entry is equal to determinant of A. If 'I' represent the Identity matrix of same order as of A and det(A) represent the determinant value of A. Then,A.adj(A) = det(A).I A non-zero square matrix 'A' of order n is said to be invertible if there exists a unique square matrix 'B' of order n such that,A.B = B.A = IThe matrix 'B' is said to be inverse of 'A'.i.e.,  B = A-1Here ,adj(AB) = (adj B).(adj A)adj( k A) = kn-1 adj(A)A-1 = (adj A) / |A|(A-1)-1 = A(AB)-1 = B-1A-1How to find Adjoint of A ? We follow the definition given above. Let A[N][N] be input matrix.1) Create a matrix adj[N][N] store the adjoint matrix.2) For every entry A[i][j] in input matrix where 0 <= i < N   and 0 <= j < N.    a) Find cofactor of A[i][j]    b) Find sign of entry.  Sign is + if (i+j) is even else       sign is odd.    c) Place the cofactor at adj[j][i]How to find Inverse? Inverse of a matrix exists only if the matrix is non-singular i.e., determinant should not be 0. Using determinant and adjoint, we can easily find the inverse of a square matrix using the below formula,  If det(A) != 0    A-1 = adj(A)/det(A)  Else    "Inverse doesn't exist"  Note: Inverse is used to find the solution to a system of linear equations.
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Function to get cofactor of mat[p][q] in cof[][]. n is
// current dimension of mat[][]
void getCof(vector<vector<int>>& mat, vector<vector<int>>& cof, 
                                        int p, int q, int n) {
    int i = 0, j = 0;
    for (int row = 0; row < n; row++) {
        for (int col = 0; col < n; col++) {
            if (row != p && col != q) {
                cof[i][j++] = mat[row][col];
                if (j == n - 1) {
                    j = 0;
                    i++;
                }
            }
        }
    }
}

// Recursive function for finding determinant 
// of matrix mat of dimension n
int getDet(vector<vector<int>>& mat, int n) {
    if (n == 1) return mat[0][0];

    int det = 0;

    // To store cofactors
    vector<vector<int>> cof(mat.size(), vector<int>(mat.size()));

    int sign = 1;
    for (int f = 0; f < n; f++) {
        getCof(mat, cof, 0, f, n);
        det += sign * mat[0][f] * getDet(cof, n - 1);
        sign = -sign;
    }
    return det;
}

// Function to get adjoint of mat in adj
void adjoint(vector<vector<int>>& mat, vector<vector<int>>& adj) {
    int n = mat.size();
    if (n == 1) {
        adj[0][0] = 1;
        return;
    }

    int sign = 1;
    vector<vector<int>> cof(n, vector<int>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            getCof(mat, cof, i, j, n);
            sign = ((i + j) % 2 == 0) ? 1 : -1;
            adj[j][i] = sign * getDet(cof, n - 1);
        }
    }
}

// Function to calculate and store inverse, returns 
// false if matrix is singular
bool inverse(vector<vector<int>>& mat, vector<vector<float>>& inv) {
    int n = mat.size();
    int det = getDet(mat, n);
    if (det == 0) {
        cout << "Singular matrix, can't find its inverse";
        return false;
    }

    vector<vector<int>> adj(n, vector<int>(n));
    adjoint(mat, adj);

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            inv[i][j] = adj[i][j] / float(det);

    return true;
}

int main() {
    vector<vector<int>> mat = { { 5, -2, 2, 7 },
                                { 1, 0, 0, 3 },
                                { -3, 1, 5, 0 },
                                { 3, -1, -9, 4 } };

    int n = mat.size();

    vector<vector<int>> adj(n, vector<int>(n)); 

    vector<vector<float>> inv(n, vector<float>(n)); 

    cout << "\nThe Adjoint is:\n";
    adjoint(mat, adj);
    for (auto& row : adj) {
        for (int val : row) cout << val << " ";
        cout << endl;
    }

    cout << "\nThe Inverse is:\n";
    if (inverse(mat, inv)) {
        for (auto& row : inv) {
            for (float val : row){
                cout << fixed << setprecision(3)<<val << " ";
            }
            cout << endl;
        }
    }

    return 0;
}


